// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ============================================================
// Mock Oracle (replace with Chainlink / Band in production)
// ============================================================
contract AYRMockOracle {
    address public owner;
    mapping(string => uint256) public prices; // 8 decimal USD prices

    modifier onlyOwner() { require(msg.sender == owner, "not owner"); _; }

    constructor() {
        owner = msg.sender;
        // Seed with approximate prices (update via setPrice)
        prices["BTC"]  = 8500000000000; // $85,000
        prices["ETH"]  = 200000000000;  // $2,000
        prices["SOL"]  = 13000000000;   // $130
        prices["BNB"]  = 60000000000;   // $600
        prices["MATIC"]= 50000000;      // $0.50
        prices["AYR"]  = 100000000;     // $1.00
    }

    function getPrice(string calldata symbol) external view returns (uint256) {
        return prices[symbol];
    }

    function setPrice(string calldata symbol, uint256 price) external onlyOwner {
        prices[symbol] = price;
    }

    function setPrices(string[] calldata symbols, uint256[] calldata _prices) external onlyOwner {
        require(symbols.length == _prices.length, "length mismatch");
        for (uint i = 0; i < symbols.length; i++) {
            prices[symbols[i]] = _prices[i];
        }
    }
}

