// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./AYRToken.sol";

// ============================================================
// Staking Contract — Open Validator Registration
// Anyone can stake AYR to become a validator
// ============================================================
contract AYRStaking {
    uint256 public constant MIN_STAKE = 1000 * 10**18; // 1000 AYR
    uint256 public constant MAX_VALIDATORS = 21;

    AYRToken public token;
    address  public owner;

    struct Validator {
        address addr;
        uint256 stake;
        bool    active;
        bool    slashed;
    }

    address[] public validatorList;
    mapping(address => Validator) public validators;

    event Registered(address indexed validator, uint256 stake);
    event Unstaked(address indexed validator, uint256 amount);
    event Slashed(address indexed validator, uint256 penalty);

    modifier onlyOwner() {
        require(msg.sender == owner, "Staking: not owner");
        _;
    }

    constructor(address _token) {
        token = AYRToken(_token);
        owner = msg.sender;
    }

    // Anyone can register as validator by staking >= MIN_STAKE
    function register(uint256 amount) external {
        require(amount >= MIN_STAKE, "Staking: below minimum stake");
        require(!validators[msg.sender].slashed, "Staking: address is slashed");
        require(token.transferFrom(msg.sender, address(this), amount), "Staking: transfer failed");

        if (validators[msg.sender].stake == 0) {
            validatorList.push(msg.sender);
        }
        validators[msg.sender].addr   = msg.sender;
        validators[msg.sender].stake  += amount;
        validators[msg.sender].active  = true;
        emit Registered(msg.sender, amount);
    }

    // Validator exits and gets stake back
    function unregister() external {
        Validator storage v = validators[msg.sender];
        require(v.active, "Staking: not active");
        uint256 amount = v.stake;
        v.stake  = 0;
        v.active = false;
        require(token.transfer(msg.sender, amount), "Staking: transfer failed");
        emit Unstaked(msg.sender, amount);
    }

    // Owner can slash misbehaving validators (burns 50%)
    function slash(address validator) external onlyOwner {
        Validator storage v = validators[validator];
        require(v.active, "Staking: not active");
        uint256 penalty = v.stake / 2;
        v.stake   -= penalty;
        v.active   = false;
        v.slashed  = true;
        // Penalty stays in contract (effectively burned)
        emit Slashed(validator, penalty);
    }

    // Returns list of active validators sorted by stake
    function getActiveValidators() external view returns (address[] memory, uint256[] memory) {
        uint256 count = 0;
        for (uint i = 0; i < validatorList.length; i++) {
            if (validators[validatorList[i]].active) count++;
        }
        address[] memory addrs  = new address[](count);
        uint256[] memory stakes = new uint256[](count);
        uint256 idx = 0;
        for (uint i = 0; i < validatorList.length; i++) {
            if (validators[validatorList[i]].active) {
                addrs[idx]  = validatorList[i];
                stakes[idx] = validators[validatorList[i]].stake;
                idx++;
            }
        }
        return (addrs, stakes);
    }

    function validatorCount() external view returns (uint256) {
        uint256 count = 0;
        for (uint i = 0; i < validatorList.length; i++) {
            if (validators[validatorList[i]].active) count++;
        }
        return count;
    }
}

