// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ============================================================
// Wrapped Token (used for wETH and wBTC bridges)
// Only the bridge minter can mint/burn
// ============================================================
contract WrappedToken {
    string  public name;
    string  public symbol;
    uint8   public constant decimals = 18;
    uint256 public totalSupply;

    address public minter;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Mint(address indexed to, uint256 amount);
    event Burn(address indexed from, uint256 amount);

    modifier onlyMinter() {
        require(msg.sender == minter, "WrappedToken: not minter");
        _;
    }

    constructor(string memory _name, string memory _symbol, address _minter) {
        name   = _name;
        symbol = _symbol;
        minter = _minter;
    }

    // Called by bridge when ETH/BTC deposit is confirmed
    function mint(address to, uint256 amount) external onlyMinter {
        totalSupply    += amount;
        balanceOf[to]  += amount;
        emit Transfer(address(0), to, amount);
        emit Mint(to, amount);
    }

    // Called by bridge when user wants to withdraw back to ETH/BTC
    function burn(address from, uint256 amount) external onlyMinter {
        require(balanceOf[from] >= amount, "WrappedToken: insufficient balance");
        balanceOf[from] -= amount;
        totalSupply     -= amount;
        emit Transfer(from, address(0), amount);
        emit Burn(from, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "WrappedToken: insufficient allowance");
        allowance[from][msg.sender] -= amount;
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(to != address(0), "WrappedToken: zero address");
        require(balanceOf[from] >= amount, "WrappedToken: insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to]   += amount;
        emit Transfer(from, to, amount);
    }
}

